          const text = lines.join("\n");
          if (turn.toolChars + text.length > MAX_TOOL_CHARS_PER_TURN) {
            throw new ToolError("\u672C\u8F6E\u8BFB\u53D6\u7684\u7AE0\u8282\u5185\u5BB9\u8FC7\u591A\u3002\u8BF7\u5148\u57FA\u4E8E\u5DF2\u7ECF\u8BFB\u5230\u7684\u5185\u5BB9\u56DE\u7B54\uFF0C\u6216\u8BA9\u7528\u6237\u5206\u51E0\u6B21\u63D0\u95EE\u3002");
          }
